import { Component } from '@angular/core';
import emailjs from '@emailjs/browser';

@Component({
  selector: 'app-contact',
  templateUrl: './contact.component.html',
  styleUrls: ['./contact.component.css']
})
export class ContactComponent {
form = {
    name: '',
    email: '',
    message: ''
  };

  sendEmail(e: Event) {
    e.preventDefault();

    emailjs.sendForm(
      'service_i0lby18',
      'template_d8gc56c',
      e.target as HTMLFormElement,
      'tkAAaMrUyBhdFYlHF'
    )
    .then(() => {
      alert('✅ Message sent successfully!');
      this.form = { name: '', email: '', message: '' };
    })
    .catch((err) => {
      console.error('FAILED:', err);
      alert('❌ Failed to send message. Try again later.');
    });
  }
}
<section class="container mt-5 contact-section fade-in" id="contact">
  <h2 class="section-title">Contact Me</h2>

  <form (submit)="sendEmail($event)" #contactForm="ngForm" class="mt-4">
    <div class="mb-3">
      <label for="from_name" class="form-label">Name</label>
      <input name="from_name" [(ngModel)]="form.name" class="form-control" required />
    </div>

    <div class="mb-3">
      <label for="reply_to" class="form-label">Email</label>
      <input name="reply_to" type="email" [(ngModel)]="form.email" class="form-control" required />
    </div>

    <div class="mb-3">
      <label for="message" class="form-label">Message</label>
      <textarea name="message" rows="4" [(ngModel)]="form.message" class="form-control" required></textarea>
    </div>

    <button type="submit" class="btn btn-success">Send Message</button>
  </form>
</section>
